def icon(name):return f'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{paths[name]}</svg>'
def button(label,ico=None,kind='secondary',href=None,disabled=False,extra=''):
 content=(icon(ico) if ico else '')+label
 if href:return f'<a class="btn {kind}" href="{href}" {extra}>{content}</a>'
 return f'<button class="btn {kind}" type="button" {"disabled" if disabled else ""} {extra}>{content}</button>'
def ib(name,label,href=None,active=False):
 content=icon(name)+f'<span class="tooltip" role="tooltip">{label}</span>'
 tag='a' if href else 'button';attr=f'href="{href}"' if href else 'type="button"'
 return f'<{tag} class="icon-btn tip {"active" if active else ""}" {attr} aria-label="{label}">{content}</{tag}>'
def badge(label,tone='neutral',ico=None):return f'<span class="badge {tone}">{icon(ico) if ico else ""}{label}</span>'
def avatar(label,ico=None):return f'<span class="avatar">{icon(ico) if ico else label}</span>'
def user(text):return f'<div class="message user-msg"><div class="message-label">{avatar("Y")}<span>You</span></div><p>{text}</p></div>'
def assistant(text):return f'<div class="message"><div class="message-label">{avatar("", "spark")}<span>CrashLab</span></div>{text}</div>'
