def shell(n,active,chat,workspace,css):
 rail=''.join(ib(ico,label,url,label==active) for ico,label,url in [('chat','Conversation',None),('cube','World','pro-1.html'),('flask','Test run','pro-2.html'),('diff','Fix','pro-3.html'),('wallet','Bounty','pro-4.html')])
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CrashLab / {active}</title><style>{base}{css}</style></head><body><header class="titlebar"><div class="brand">{icon('cube')}CrashLab<span class="project">Dubai cleaning {icon('down')}</span></div><button class="command" type="button">{icon('search')}Search commands…<kbd>⌘ K</kbd></button><div class="windows">{ib('minus','Minimize window')}{ib('square','Resize window')}{ib('x','Close window')}</div></header><main class="shell"><aside class="activity" aria-label="Activity bar">{rail}<div class="bottom">{ib('settings','Settings')}</div></aside><aside class="chat"><header class="chat-head"><strong>Chat</strong><div class="actions">{ib('history','Conversation history')}{ib('plus','New conversation')}</div></header><div class="chat-content">{chat}</div>{composer()}</aside><section class="workspace">{tabs(active)}<div class="workspace-body">{workspace}</div></section></main><footer class="statusbar"><div class="flex">{icon('shield')}Simulated<span style="margin-left:12px">Hand-built physics / Not hardware-validated</span></div><span>Run totals supplied / Scene values and code are sample</span><div class="flex">Sample data<span style="margin-left:12px">Local session</span></div></footer></body></html>'''
def head(crumb,title,actions=''):
 return f'<header class="page-head"><div><p class="breadcrumb">{crumb}</p><h1>{title}</h1></div><div class="flex">{badge("Simulated","neutral","cube")}{actions}</div></header>'
def write(n,active,chat,workspace,css): (root/f'pro-{n}.html').write_text(shell(n,active,chat,workspace,css))
render='real-frames-hd/render-still.png'
def viewport(height='',label='Perspective / Façade camera',toast=False):
 return f'''<figure class="viewport" style="{height}"><img src="{render}" alt="Supplied simulation render of a tethered window-cleaning robot on a glass tower"><figcaption class="viewport-label">{icon('eye')}{label}</figcaption>{f'<div class="toast" role="status">{icon("check")}<span>World ready <span class="muted">/ 1 recorded test</span></span></div>' if toast else ''}</figure>'''
def transport(time='12.40',end='24.00'):
 return f'<div class="transport">{ib("back","Previous frame")}{ib("play","Play recorded run")}{ib("next","Next frame")}<span>{time} <span class="subtle">/ {end} s</span></span><span class="grow"></span><select class="select" aria-label="Playback speed" style="height:24px"><option>1×</option><option>0.5×</option><option>2×</option></select>{ib("refresh","Loop playback")}</div>'
# Screen 1: viewport-first authoring.
chat=user("Build a window-cleaning robot for towers in Dubai. Start with a glass façade and a steady wind.")
chat+=assistant(f'''<p>The world is ready. The baseline test completed without a detected failure.</p><ul class="step-list"><li>{icon('check')}Built world<span class="duration">4.2 s</span></li><li>{icon('check')}Attached controller<span class="duration">Session copy</span></li><li>{icon('check')}Ran 1 test<span class="duration">24.0 s</span></li></ul><div class="context-row"><span class="context-chip">{icon('file')}façade.world</span><span class="context-chip">{icon('code')}controller.py</span></div>''')
chat+=f'''<section class="approval">{badge('Approval required','blue','shield')}<h3>Run the proposed campaign?</h3><p>52 worlds cover wind, dust, wetness and contact edges. Invalid cases will be held; unstable results stay separate.</p><div class="approval-actions">{button('Run campaign','play','primary','pro-2.html')}{button('Review',kind='secondary',href='pro-2.html')}</div></section><div class="notice">{icon('info')}<span>Simplified physics. Seal ageing and tether fatigue remain untested.</span></div>'''
css='''.world-layout{display:grid;grid-template-columns:minmax(0,1fr) 248px;height:732px}.world-main{min-width:0;display:grid;grid-template-rows:40px 456px 152px 84px}.world-inspector{background:var(--panel);border-left:1px solid var(--border)}.world-main .viewport img{object-position:68% center}.inspector-title{height:40px;display:flex;align-items:center;justify-content:space-between;padding:0 16px;border-bottom:1px solid var(--border);font-size:12px}.world-note{padding:12px 16px;display:flex;align-items:flex-start;gap:8px;color:var(--muted);font-size:12px;line-height:1.6;border-top:1px solid var(--border)}.world-note .icon{margin-top:4px}.tree-area{padding:8px}.viewport-footer{display:flex;justify-content:space-between;font-size:11px;color:var(--subtle);margin-top:12px}.inspector-section .select{width:100%;margin-top:4px}.inspect-help{font-size:11px;color:var(--subtle);margin-top:12px;line-height:1.6}'''
workspace=head('World / Dubai façade','Baseline world',button('Run test','play','primary',href='pro-2.html'))
workspace+=f'''<div class="world-layout"><section class="world-main"><div class="toolbar">{ib('mouse','Select tool',active=True)}{ib('eye','Camera view')}<span class="toolbar-divider"></span><div class="segmented" aria-label="Viewport mode"><button class="segment active" aria-pressed="true">3D</button><button class="segment" aria-pressed="false">2D</button></div><span class="grow"></span><span class="small muted">Replay of recorded run</span>{ib('expand','Fit viewport')}</div>{viewport(toast=True)}<section class="timeline" aria-label="Recorded run timeline">{transport()}<input class="scrub" type="range" min="0" max="2400" value="1240" aria-label="Recorded time"><div class="time-labels"><span>0 s</span><span>6 s</span><span>12 s</span><span>18 s</span><span>24 s</span></div><div class="tracks"><span>Robot path</span><div class="track"><span style="width:100%"></span><i class="marker" style="left:52%"></i></div></div></section><div class="world-note">{icon('info')}<div><p>Baseline recording / No detected failure</p><p class="small subtle">A pass applies to this run only. Campaign results keep held and flaky worlds separate.</p></div></div></section><aside class="world-inspector"><div class="inspector-title"><strong>Inspector</strong>{ib('settings','Inspector settings')}</div><div class="tree-area"><div class="tree-row">{icon('down')}{icon('folder')}World</div><div class="tree-row indent">{icon('cube')}Glass façade</div><div class="tree-row indent selected" aria-current="true">{icon('square')}Cleaning robot</div><div class="tree-row indent">{icon('wind')}Environment</div></div><section class="inspector-section"><div class="section-label">Environment{icon('settings')}</div><label class="property">Wind <input value="2.0 m/s" aria-label="Wind speed" readonly></label><label class="property">Gust <input value="5.0 m/s" aria-label="Gust speed" readonly></label><label class="property">Wetness <input value="0.10" aria-label="Surface wetness" readonly></label><p class="inspect-help">Sample values. Wind affects load; wetness changes contact friction.</p></section><section class="inspector-section"><div class="section-label">Robot</div><label class="property">Suction <input value="42.0 kPa" aria-label="Suction magnitude" readonly></label><div class="property"><span>Tether</span><span class="value">Attached</span></div><div class="property"><span>Controller</span><span class="value">Session copy</span></div></section><section class="inspector-section"><label class="section-label" for="camera">Camera</label><select class="select" id="camera"><option>Façade camera</option><option>Robot follow</option></select><p class="inspect-help">Recorded still shown. Scrubbing does not play video in this study.</p></section></aside></div>'''
write(1,'World',chat,workspace,css)
# Screen 2: execution, classification and selection.
chat=user('Run the full suite. Keep held and flaky worlds separate from passes.')
chat+=assistant(f'''<p>The campaign classified all 52 worlds.</p><ul class="step-list"><li>{icon('check')}Generated 52 worlds<span class="duration">Complete</span></li><li>{icon('check')}Held 13 before execution<span class="duration">Review</span></li><li>{icon('check')}Ran 39 eligible worlds<span class="duration">Complete</span></li><li>{icon('check')}Controls passed<span class="duration">10 / 10</span></li></ul><p><span class="red">31 failed</span>, <span class="amber">5 were flaky</span>, and <span class="green">3 passed</span>. Held worlds have no verdict.</p>''')
chat+=f'''<section class="approval"><div class="flex">{icon('search')}<h3 style="margin:0">Inspect the repeated slip</h3></div><p style="margin-top:8px">W-018 shows slip during the gust. Open the recorded run alongside its signals and controller trace.</p><div class="approval-actions">{button('Inspect W-018','eye','primary','pro-3.html')}</div></section><div class="notice">{icon('info')}<span>A flaky result is not a pass. Rerun stability is part of the evidence.</span></div><div class="context-row"><span class="context-chip">{icon('file')}campaign-014</span><span class="context-chip">{icon('code')}controller.py</span></div>'''
css='''.pipeline{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;padding:12px 20px;border-bottom:1px solid var(--border);background:var(--panel)}.pipeline-step .top{display:flex;gap:8px;align-items:center;font-size:12px;margin-bottom:8px}.pipeline-step .top .icon{width:14px;height:14px;color:var(--green)}.pipeline-step .top span:last-child{margin-left:auto;color:var(--muted);font-size:11px}.run-stats{grid-template-columns:repeat(6,1fr)}.run-stats .stat{padding:12px 20px}.filters{display:flex;gap:12px;align-items:center;padding:12px 20px}.filters .input-wrap{margin-left:auto;width:192px}.results-layout{display:grid;grid-template-columns:minmax(0,1fr) 224px;padding:0 20px 16px;gap:20px}.heat-panel{border-left:1px solid var(--border);padding-left:20px}.heatmap{display:grid;grid-template-columns:repeat(8,1fr);gap:4px;margin:12px 0}.heat-cell{height:20px;border-radius:4px;display:flex;align-items:center;justify-content:center;font-size:11px}.heat-cell.failed{background:#4B2A32;color:var(--red)}.heat-cell.held{background:#363126;color:var(--amber)}.heat-cell.flaky{background:#51402A;color:var(--amber)}.heat-cell.passed{background:#233D30;color:var(--green)}.heat-cell.selected{outline:2px solid var(--accent);outline-offset:1px}.legend{display:grid;grid-template-columns:1fr 1fr;gap:8px;font-size:11px;color:var(--muted);margin-top:12px}.heat-panel .empty-state{border-top:1px solid var(--border);margin-top:20px;padding-left:0;padding-right:0}.sort-btn{display:flex;align-items:center;gap:4px;padding:0;border:0;background:transparent;font-size:11px;color:var(--text)}'''
workspace=head('Campaign 014 / Completed','Test run',button('Export','download','secondary'))
workspace+='<div class="pipeline">'
for label,count in [('Generate','52 worlds'),('Validate','13 held'),('Execute','39 completed'),('Controls','10 / 10')]:
 workspace+=f'<div class="pipeline-step"><div class="top">{icon("check")}<span>{label}</span><span>{count}</span></div><progress max="100" value="100" aria-label="{label} complete"></progress></div>'
workspace+='</div><div class="stats run-stats">'
for label,val,tone in [('Worlds','52',''),('Failed','31','red'),('Held','13','amber'),('Flaky','5','amber'),('Passed','3','green'),('Controls','10/10','green')]:workspace+=f'<div class="stat"><p class="label">{label}</p><p class="value {tone}">{val}</p></div>'
workspace+=f'''</div><div class="filters"><div class="segmented" aria-label="Status filter"><button class="segment active" aria-pressed="true">All 52</button><button class="segment" aria-pressed="false">Failed 31</button><button class="segment" aria-pressed="false">Held 13</button></div><select class="select" aria-label="Scenario group"><option>All groups</option><option>Wind + dust</option><option>Contact</option></select><label class="input-wrap">{icon('search')}<input placeholder="Find a world…" aria-label="Find a world"></label></div><div class="results-layout"><section><table class="data-table"><colgroup><col style="width:112px"><col style="width:100px"><col style="width:116px"><col><col style="width:120px"></colgroup><thead><tr><th>World</th><th aria-sort="ascending"><button class="sort-btn">Status {icon('sort')}</button></th><th>Group</th><th>Failure type</th><th class="num">Key metric</th></tr></thead><tbody>'''
rows=[('W-018','Failed','Wind + dust','Slip distance','0.18 m'),('W-021','Failed','Wind','Seal loss','26.4 kPa'),('W-024','Failed','Contact','Edge collision','0.12 m'),('W-027','Failed','Wetness','Slip distance','0.14 m'),('W-031','Failed','Wind + dust','Slip distance','0.21 m'),('W-046','Flaky','Wind','Slip varies','4 / 8 repeats'),('W-033','Held','Contact','Invalid geometry','Not run'),('W-041','Held','Heat','Missing model','Not run'),('W-050','Passed','Nominal','None detected','0.01 m'),('W-052','Passed','Nominal','None detected','0.02 m')]
for name,status,group,failure,metric in rows:
 tone,ico={'Failed':('red','x'),'Held':('amber','pause'),'Flaky':('amber','refresh'),'Passed':('green','check')}[status]
 name_cell=f'<a href="pro-3.html">{name}</a>' if name=='W-018' else name
 workspace+=f'<tr class="{"selected" if name=="W-018" else ""}" {"aria-selected=true" if name=="W-018" else ""}><td class="name">{name_cell}</td><td>{badge(status,tone,ico)}</td><td class="muted">{group}</td><td>{failure}</td><td class="num">{metric}</td></tr>'
workspace+=f'''</tbody></table><div class="table-footer"><span>10 of 52 worlds / Sample rows</span><div class="flex">{button('Previous',disabled=True)}{button('Next')}</div></div></section><aside class="heat-panel"><h3>Campaign map</h3><p class="tiny subtle">52 classified worlds</p><div class="heatmap" aria-label="31 failed, 13 held, 5 flaky and 3 passed worlds">'''
for i in range(52):
 status='failed' if i<31 else 'held' if i<44 else 'flaky' if i<49 else 'passed'
 workspace+=f'<span class="heat-cell {status} {"selected" if i==17 else ""}" title="World {i+1}: {status}" aria-label="World {i+1}, {status}">{i+1}</span>'
workspace+=f'''</div><div class="legend"><span class="red">31 failed</span><span class="amber">13 held</span><span class="amber">5 flaky</span><span class="green">3 passed</span></div><section class="empty-state">{icon('pause')}<h3>Held means not run</h3><p>No replay or pass verdict exists for held worlds.</p>{button('Run held worlds',disabled=True)}</section></aside></div>'''
write(2,'Test run',chat,workspace,css)
# Screen 3: recorded failure + evidence-aware code review.
chat=user('Trace this failure to the controller and try a fix in the session copy.')
chat+=assistant('''<p>The candidate improves fresh-world passes from <strong>11 to 17</strong> out of <strong>104</strong>. <strong>0 became worse</strong>.</p><p class="muted">It removes a guard. The improvement is evidence to review, not proof the guard is unnecessary.</p>''')
chat+=f'''<div class="between" style="margin-bottom:12px">{badge('Not applied','amber','pause')}<span class="tiny muted">Evaluation / 104 fresh worlds</span></div><div class="diff"><div class="diff-head"><span>{icon('code')} controller.py</span><span class="red">−2</span></div><div class="code-block" style="padding:8px 0"><div class="code-line removed"><span class="line-no">88 −</span><code>if abs(wind_ms) &gt; 18:</code></div><div class="code-line removed"><span class="line-no">89 −</span><code>    return HOLD</code></div><div class="code-line"><span class="line-no">90</span><code>target = compute_target(state)</code></div></div></div><div class="notice" style="margin-top:12px">{icon('alert')}<span><strong class="amber">Guard removed</strong><br>Review high-wind behavior before accepting this candidate.</span></div><div class="approval-actions">{button('Accept','check','primary')}{button('Reject','x','secondary')}</div><p class="tiny subtle" style="margin-top:8px">Acceptance updates the session copy only.<br>The real controller has not changed.</p>'''
css='''.failure-content{padding:16px 20px}.evidence-top{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:16px}.replay-panel{min-width:0;border:1px solid var(--border);border-radius:6px}.replay-panel .toolbar{height:32px;border-radius:6px 6px 0 0}.replay-panel .viewport{height:260px}.replay-panel .viewport img{object-position:76% 56%}.replay-panel .transport{padding:8px 12px;background:var(--panel)}.signal{background:var(--panel);padding:12px;border-radius:6px;height:160px}.signal+.signal{margin-top:12px}.signal .value{font-size:16px;font-weight:600}.signal-head{display:flex;align-items:baseline;justify-content:space-between;margin-bottom:8px}.signal h3{font-size:12px;font-weight:500;color:var(--muted)}.signal svg.chart{width:100%;height:96px;display:block}.chart text{font:11px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;fill:var(--subtle)}.event-timeline{margin-top:16px;padding:12px 16px;background:var(--panel);border:1px solid var(--border);border-radius:6px}.event-track{position:relative;margin:12px 0 8px;height:24px;border-top:1px solid var(--border)}.event-marker{position:absolute;top:-5px;width:8px;height:8px;border-radius:0;background:var(--amber);transform:rotate(45deg)}.event-marker.failure{background:var(--red)}.event-marker.selected{outline:2px solid var(--red);outline-offset:3px}.event-time{display:flex;justify-content:space-between;font-size:11px;color:var(--muted);margin-top:8px}.event-list{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;font-size:12px}.event-list time{font-size:11px;color:var(--subtle);margin-right:8px}.controller{margin-top:16px;border:1px solid var(--border);border-radius:6px;background:var(--panel)}.controller-head{padding:8px 12px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;font-size:12px}.controller .code-block{padding:8px 0}.evidence-foot{margin-top:12px;display:flex;justify-content:space-between;color:var(--subtle);font-size:11px}'''
def chart(kind):
 if kind=='suction':
  line='M30 32L65 33 84 33 100 35 122 42 133 55 143 70 172 72 211 73 246 74';unitlabels=[('48',22),('36',51),('24',80)]
 else:
  line='M30 25L65 26 84 26 100 29 122 36 133 47 143 66 172 70 211 69 246 71';unitlabels=[('1.4',22),('1.0',51),('0.6',80)]
 return f'''<svg class="chart" viewBox="0 0 256 96" role="img" aria-label="Sample {kind} signal falling around the selected failure"><path d="M30 18H248M30 47H248M30 76H248" fill="none" stroke="#292E36" stroke-width="1"/><path d="M143 12v68" stroke="#F18B91" stroke-dasharray="3 3"/><path d="{line}" fill="none" stroke="#91A7FF" stroke-width="2"/><rect x="140" y="{67 if kind=='suction' else 63}" width="6" height="6" fill="#F18B91"/>{''.join(f'<text x="0" y="{y}">{label}</text>' for label,y in unitlabels)}<text x="30" y="92">28 s</text><text x="121" y="92">32.2 s</text><text x="222" y="92">36 s</text></svg>'''
workspace=head('Campaign 014 / W-018 / Failure detail','Slip distance exceeded',badge('Failed','red','x')+button('Apply to controller',kind='secondary',disabled=True))
workspace+=f'''<div class="failure-content"><div class="evidence-top"><section class="replay-panel"><div class="toolbar">{icon('play')}<span class="small">Replay of recorded run</span><span class="grow"></span>{ib('expand','Expand replay')}</div>{viewport(label='W-018 / Sample still')}{transport('32.20','48.20')}</section><aside><section class="signal"><div class="signal-head"><h3>Suction pressure</h3><span class="value red">26.4 <span class="small muted">kPa</span></span></div>{chart('suction')}</section><section class="signal"><div class="signal-head"><h3>Grip margin</h3><span class="value red">0.74 <span class="small muted">ratio</span></span></div>{chart('grip')}</section></aside></div><section class="event-timeline"><div class="between"><h3>Event timeline</h3><span class="small muted">Selected / 32.20 s</span></div><div class="event-track"><i class="event-marker" style="left:33.33%"></i><i class="event-marker" style="left:56.67%"></i><i class="event-marker failure selected" style="left:70%"></i><div class="event-time"><span>28.0 s</span><span>30.0 s</span><span>32.0 s</span><span>34.0 s</span></div></div><div class="event-list"><span><time>30.00</time>Gust begins</span><span><time>31.40</time>Suction drops</span><span class="red"><time>32.20</time>Slip reaches 0.18 m</span></div></section><section class="controller" id="controller"><div class="controller-head"><span class="flex">{icon('code')}controller.py <span class="subtle">/ Baseline at event</span></span><span class="small muted">Line 88 {icon('link')}</span></div><div class="code-block"><div class="code-line"><span class="line-no">86</span><code><span class="syntax-comment"># High-wind fallback</span></code></div><div class="code-line"><span class="line-no">87</span><code>wind_ms = state.<span class="syntax-name">wind_speed</span></code></div><div class="code-line current"><span class="line-no">88</span><code><span class="syntax-key">if</span> <span class="syntax-fn">abs</span>(wind_ms) &gt; <span class="syntax-number">18</span>:</code></div><div class="code-line"><span class="line-no">89</span><code>    <span class="syntax-key">return</span> HOLD</code></div><div class="code-line"><span class="line-no">90</span><code>target = <span class="syntax-fn">compute_target</span>(state)</code></div></div></section><div class="evidence-foot"><span>Signals, event timings and code are illustrative.</span><span>Candidate not applied</span></div></div>'''
write(3,'Fix',chat,workspace,css)
# Screen 4: gate evidence and local ledger, never a payment confirmation.
chat=user('Prepare a bounty for the gaps the model did not test. Check submitted worlds before recording any reward.')
chat+=assistant(f'''<p>The bounty is using a <strong>local ledger</strong>. No funds have moved on chain.</p><ul class="step-list"><li>{icon('check')}Created local draft<span class="duration">3 gaps</span></li><li>{icon('check')}Reserved local budget<span class="duration">1,000 USDC</span></li><li>{icon('check')}Evaluated submissions<span class="duration">3 checked</span></li></ul><p>Submission 3 repeated the failure in <strong>7 of 8</strong> reruns. The reference twin passed.</p>''')
chat+=f'''<section class="approval">{badge('Gate satisfied','green','check')}<h3>New valid failure</h3><p>100 USDC is recorded as a local credit. This is not an on-chain payment.</p><div class="approval-actions">{button('Review evidence','eye','primary',href='#verdict')}</div></section><div class="notice">{icon('info')}<span>The reference twin passed near this world. This does not prove the submitted world is physically possible.</span></div>'''
css='''.bounty-stats{grid-template-columns:repeat(4,1fr)}.bounty-stats .stat{padding:12px 20px}.bounty-content{padding:16px 20px}.bounty-grid{display:grid;grid-template-columns:minmax(0,1fr) 304px;gap:20px}.submissions-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.submission-table td{height:56px}.submission-table th{font-size:11px}.submission-table .subline{display:block;color:var(--subtle);font-size:11px;margin-top:2px}.verdict{background:var(--panel);border:1px solid var(--border);border-radius:6px;padding:12px}.verdict h2{margin:12px 0 4px}.verdict .verdict-copy{color:var(--muted);font-size:12px;line-height:1.6}.gate-list{list-style:none;margin:12px 0;padding:0}.gate-list li{display:flex;align-items:center;gap:8px;margin:6px 0;font-size:12px}.gate-list .icon{width:14px;height:14px;color:var(--green)}.gate-list .value{margin-left:auto;color:var(--muted)}.gate-evidence{border-top:1px solid var(--border);padding-top:12px}.gate-evidence .property{font-size:12px;min-height:24px}.gaps{margin-top:16px;padding-top:12px;border-top:1px solid var(--border)}.gap-row{display:flex;align-items:center;gap:8px;height:24px;color:var(--muted);font-size:12px}.gap-row .icon{width:14px;height:14px}.gap-row .badge{margin-left:auto}.ledger{margin-top:16px;border:1px solid var(--border);border-radius:6px;padding:12px;background:var(--panel)}.ledger-top{display:flex;align-items:center;justify-content:space-between}.ledger-stepper{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:12px 0}.ledger-step{border-top:2px solid var(--border);padding-top:8px;display:flex;align-items:center;gap:8px;font-size:12px;color:var(--muted)}.ledger-step.done{border-color:#42694F}.ledger-step .icon{width:14px;height:14px;color:var(--green)}.ledger-note{display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--border);padding-top:8px;font-size:12px;color:var(--muted)}.ledger-note .btn{height:24px;font-size:12px}.bounty-toast{position:static;margin-top:16px;display:flex;background:var(--raised);border-radius:6px;padding:8px 12px;font-size:12px;align-items:center;gap:8px}.bounty-toast .icon{color:var(--green)}.local-empty{margin-top:12px;padding:12px;text-align:left;background:var(--raised);border-radius:6px}.local-empty .empty-icon{float:left;margin-right:12px}.local-empty h3{font-size:12px}.local-empty p{font-size:11px;color:var(--subtle);margin-top:4px}'''
