workspace+=f'''</div><div class="bounty-content"><div class="bounty-grid"><section><div class="submissions-head"><h2>Submissions</h2><div class="flex">{badge('3 evaluated')}{button('Import world','plus','secondary')}</div></div><table class="data-table submission-table"><colgroup><col style="width:116px"><col style="width:108px"><col><col style="width:76px"></colgroup><thead><tr><th aria-sort="descending">Submission {icon('down')}</th><th>Status</th><th>Gate result</th><th class="num">Reruns</th></tr></thead><tbody><tr class="selected" aria-selected="true"><td class="name"><a href="#verdict">Submission 3</a><span class="subline">Tester 03</span></td><td>{badge('Accepted','green','check')}</td><td>New slip failure</td><td class="num">7 / 8</td></tr><tr><td class="name">Submission 2<span class="subline">Tester 02</span></td><td>{badge('Rejected','red','x')}</td><td>No failure found</td><td class="num">0 / 1</td></tr><tr><td class="name">Submission 1<span class="subline">Tester 01</span></td><td>{badge('Rejected','red','x')}</td><td>Invalid world file</td><td class="num">Not run</td></tr></tbody></table><section class="gaps"><h3>Requested coverage</h3><div class="gap-row">{icon('shield')}Long-term seal wear{badge('Not modelled')}</div><div class="gap-row">{icon('shield')}Water ingress{badge('Not modelled')}</div><div class="gap-row">{icon('shield')}Tether and anchor fatigue{badge('Not modelled')}</div></section><div class="local-empty"><span class="empty-icon">{icon('wallet')}</span><h3>No on-chain transaction</h3><p>No wallet or transaction hash exists in local mode.</p></div></section><aside class="verdict" id="verdict">{badge('Accepted','green','check')}<h2>Submission 3</h2><p class="verdict-copy">A new slip-distance failure met the repeatability gate.</p><ul class="gate-list"><li>{icon('check')}Schema valid<span class="value">Passed</span></li><li>{icon('check')}Failure repeats<span class="value">7 / 8</span></li><li>{icon('check')}Reference twin<span class="value">Passed</span></li><li>{icon('check')}Failure identity<span class="value">New</span></li></ul><div class="gate-evidence"><div class="property"><span>Gate requires</span><span class="value">7 of 8</span></div><div class="property"><span>Local reward</span><span class="value">100 USDC</span></div><p class="tiny subtle" style="margin-top:12px">Simulated gate. Not hardware validation.</p></div></aside></div><section class="ledger"><div class="ledger-top"><h3>Ledger state</h3>{badge('Local ledger. Not on chain.','amber','wallet')}</div><div class="ledger-stepper"><div class="ledger-step done">{icon('check')}Draft created</div><div class="ledger-step done">{icon('check')}Budget reserved</div><div class="ledger-step done">{icon('check')}Gate satisfied</div><div class="ledger-step done">{icon('check')}Local credit recorded</div></div><div class="ledger-note"><span>Remaining local budget: <strong class="muted">900 USDC</strong></span>{button('View transaction','link','secondary',disabled=True)}</div></section></div>'''
